#include <cell/action_history.hpp>
#include <iostream>
using namespace cell::history;
namespace {void need(bool v,const char*m){if(!v)throw std::runtime_error(m);}struct Add:Action{int&value;int delta;bool failPerform{},failUndo{};Add(int&v,int n):value(v),delta(n){}bool perform()override{if(failPerform)return false;value+=delta;return true;}bool undo()override{if(failUndo)return false;value-=delta;return true;}};struct Set:Action{int&value;int before,after;bool throwMerge{};Set(int&v,int a,int b,bool throws=false):value(v),before(a),after(b),throwMerge(throws){}bool perform()override{value=after;return true;}bool undo()override{value=before;return true;}Action*createCoalescedAction(Action*next)override{if(throwMerge)throw std::bad_alloc();auto*n=dynamic_cast<Set*>(next);return n&&&n->value==&value&&after==n->before?new Set(value,before,n->after):nullptr;}};}
int main(){try{ActionHistory h;int value=0;for(int n=0;n<5000;++n){h.beginNewTransaction("Edit "+cell::Text(n));need(h.perform(new Add(value,1)),"Edit admission failed");}need(value==5000&&h.transactionCount()==5000&&h.getUndoDescriptions().size()==5000,"History imposed a fixed count or lost edits");for(int n=0;n<5000;++n)need(h.undo(),"Undo missing");need(value==0&&!h.canUndo(),"Undo did not restore source");for(int n=0;n<5000;++n)need(h.redo(),"Redo missing");need(value==5000,"Redo changed result");
 need(h.undo(),"Branch undo failed");auto*failed=new Add(value,10);failed->failPerform=true;h.beginNewTransaction("Rejected edit");need(!h.perform(failed)&&h.canRedo()&&value==4999,"Failed admission destroyed redo");need(h.perform(new Add(value,2))&&!h.canRedo()&&value==5001,"Successful branch retained invalid redo");
 h.clearUndoHistory();value=0;h.beginNewTransaction("One gesture");need(h.perform(new Set(value,0,1))&&h.perform(new Set(value,1,2)),"Coalesced edit failed");need(h.getNumActionsInCurrentTransaction()==1&&h.undo()&&value==0&&h.redo()&&value==2,"One gesture lost before/after state");
 h.clearUndoHistory();value=0;h.beginNewTransaction("Memory pressure");need(h.perform(new Set(value,0,1,true))&&h.perform(new Set(value,1,2)),"Coalescing allocation failure lost accepted edit");need(h.getNumActionsInCurrentTransaction()==2&&h.undo()&&value==0,"Fallback delta could not undo");
 h.clearUndoHistory();value=0;h.beginNewTransaction("Grouped edit");auto*a=new Add(value,2);need(h.perform(a)&&h.perform(new Add(value,3)),"Group setup failed");a->failUndo=true;need(!h.undo()&&value==5&&h.canUndo(),"Failed group undo did not roll back completed operations");a->failUndo=false;need(h.undo()&&value==0,"Recovered group undo failed");a->failPerform=true;need(!h.redo()&&value==0&&h.canRedo(),"Failed redo changed source/history");a->failPerform=false;need(h.redo()&&value==5,"Recovered redo failed");
 std::cout<<"PASS native action history: 5000 transactions, branch/failure safety, coalescing, allocation fallback, grouped rollback and redo\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
